41	static inline bool nvl_fabric_supported() {
42	    int device_id;
43	    CUDACHECK(cudaGetDevice(&device_id));
44	    CUdevice cu_device;
45	    CUCHECK(cuDeviceGet(&cu_device, device_id));
46	    int supported = 0;
47	    CUresult err = cuDeviceGetAttribute(&supported,
48	        CU_DEVICE_ATTRIBUTE_HANDLE_TYPE_FABRIC_SUPPORTED, cu_device);
49	    // Older drivers do not know the attribute at all.
50	    if (err != CUDA_SUCCESS || !supported) return false;
51	
52	    CUmemAllocationProp prop = {};
53	    prop.type = CU_MEM_ALLOCATION_TYPE_PINNED;
54	    prop.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
55	    prop.location.id = device_id;
56	    prop.requestedHandleTypes = CU_MEM_HANDLE_TYPE_FABRIC;
57	    size_t size;
58	    if (cuMemGetAllocationGranularity(
59	            &size, &prop, CU_MEM_ALLOC_GRANULARITY_RECOMMENDED) != CUDA_SUCCESS)
60	        return false;
61	
62	    CUmemGenericAllocationHandle handle;
63	    if (cuMemCreate(&handle, size, &prop, 0) != CUDA_SUCCESS) return false;
64	    CUCHECK(cuMemRelease(handle));
65	    return true;
66	}
