68	static inline size_t nvl_granularity_for(int device_id,
69	                                         CUmemAllocationHandleType ht) {
70	    CUmemAllocationProp prop = {};
71	    prop.type = CU_MEM_ALLOCATION_TYPE_PINNED;
72	    prop.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
73	    prop.location.id = device_id;
74	    prop.requestedHandleTypes = ht;
75	
76	    size_t granularity;
77	    CUCHECK(cuMemGetAllocationGranularity(
78	        &granularity, &prop, CU_MEM_ALLOC_GRANULARITY_RECOMMENDED));
79	    return granularity;
80	}
