82	static inline size_t nvl_granularity_max(int device_id) {
83	    size_t gran = nvl_granularity_for(
84	        device_id, CU_MEM_HANDLE_TYPE_POSIX_FILE_DESCRIPTOR);
85	    if (nvl_fabric_supported()) {
86	        gran = std::max(
87	            gran, nvl_granularity_for(device_id, CU_MEM_HANDLE_TYPE_FABRIC));
88	    }
89	    return gran;
90	}
