92	static inline CUmemAllocationHandleType nvl_handle_type(bool use_fabric) {
93	    return use_fabric ? CU_MEM_HANDLE_TYPE_FABRIC
94	                      : CU_MEM_HANDLE_TYPE_POSIX_FILE_DESCRIPTOR;
95	}
