97	static inline std::tuple<size_t, size_t, int> nvl_prepare(
98	    const std::vector<int64_t> &shape,
99	    at::ScalarType dtype,
100	    bool use_fabric
101	) {
102	    TORCH_CHECK(!shape.empty(), "Shape must be non-empty");
103	
104	    int device_id;
105	    CUDACHECK(cudaGetDevice(&device_id));
106	
107	    size_t size = c10::elementSize(dtype);
108	    for (auto dim : shape) {
109	        TORCH_CHECK(dim > 0, "Size dimensions must be positive");
110	        size *= static_cast<size_t>(dim);
111	    }
112	
113	    size_t granularity = nvl_granularity_for(
114	        device_id, nvl_handle_type(use_fabric));
115	    size_t allocated_size = (size + granularity - 1) / granularity * granularity;
116	
117	    return {size, allocated_size, device_id};
118	}
