120	static inline at::Tensor make_vmm_tensor(
121	    void *ptr,
122	    size_t nbytes,
123	    size_t allocated_size,
124	    int device_id,
125	    const std::vector<int64_t> &shape,
126	    at::ScalarType dtype
127	) {
128	    auto deleter = [device_id, ptr, allocated_size](void *p) {
129	        if (!p) return;
130	        c10::cuda::CUDAGuard guard(device_id);
131	        cudaStreamSynchronize(c10::cuda::getCurrentCUDAStream().stream());
132	        cuMemUnmap(reinterpret_cast<CUdeviceptr>(ptr), allocated_size);
133	        cuMemAddressFree(reinterpret_cast<CUdeviceptr>(ptr), allocated_size);
134	    };
135	
136	    auto storage = c10::Storage(
137	        c10::Storage::use_byte_size_t(),
138	        static_cast<int64_t>(nbytes),
139	        at::InefficientStdFunctionContext::makeDataPtr(
140	            ptr, std::move(deleter), c10::Device(c10::kCUDA, device_id)),
141	        /*allocator=*/nullptr,
142	        /*resizable=*/false);
143	
144	    auto impl = c10::make_intrusive<at::TensorImpl>(
145	        std::move(storage),
146	        c10::DispatchKeySet(c10::DispatchKey::CUDA),
147	        c10::scalarTypeToTypeMeta(dtype));
148	    impl->set_sizes_contiguous(shape);
149	    return at::Tensor(std::move(impl));
150	}
