152	static constexpr int64_t kFabricHandleBytes =
153	    static_cast<int64_t>(sizeof(CUmemFabricHandle::data));
154	
155	// Export an allocation (or multicast object) as a CPU tensor matching
156	// `use_fabric`: uint8[64] holding a CUmemFabricHandle, or int64[] (a scalar
157	// tensor) holding a POSIX fd.
158	static inline at::Tensor nvl_export_shareable(
159	    CUmemGenericAllocationHandle handle, bool use_fabric
160	) {
161	    if (use_fabric) {
162	        CUmemFabricHandle fabric = {};
163	        CUCHECK(cuMemExportToShareableHandle(
164	            &fabric, handle, CU_MEM_HANDLE_TYPE_FABRIC, 0));
165	        auto out = at::empty({kFabricHandleBytes},
166	                             at::TensorOptions().dtype(at::kByte));
167	        std::memcpy(out.data_ptr(), fabric.data, sizeof(fabric.data));
168	        return out;
169	    }
170	    int fd = -1;
171	    CUCHECK(cuMemExportToShareableHandle(
172	        &fd, handle, CU_MEM_HANDLE_TYPE_POSIX_FILE_DESCRIPTOR, 0));
173	    TORCH_CHECK(fd >= 0, "cuMemExportToShareableHandle returned invalid fd");
174	    return at::scalar_tensor(fd, at::TensorOptions().dtype(at::kLong));
175	}
