177	static inline void nvl_check_handles(
178	    const at::Tensor &handles, int64_t world_size, bool use_fabric
179	) {
180	    TORCH_CHECK(handles.device().is_cpu() && handles.is_contiguous(),
181	        "shareable handles must be a contiguous CPU tensor, got device=",
182	        handles.device(), " contiguous=", handles.is_contiguous());
183	    if (use_fabric) {
184	        TORCH_CHECK(handles.scalar_type() == at::kByte && handles.dim() == 2
185	                    && handles.size(0) == world_size
186	                    && handles.size(1) == kFabricHandleBytes,
187	            "fabric handles must be uint8[", world_size, ", ",
188	            kFabricHandleBytes, "], got ", handles.scalar_type(), handles.sizes());
189	    } else {
190	        TORCH_CHECK(handles.scalar_type() == at::kLong
191	                    && handles.numel() == world_size,
192	            "fd handles must be int64 with ", world_size, " elements, got ",
193	            handles.scalar_type(), handles.sizes());
194	    }
195	}
