197	// Import row `index` of a handle tensor already validated by nvl_check_handles.
198	static inline CUmemGenericAllocationHandle nvl_import_shareable(
199	    const at::Tensor &handles, int64_t index, bool use_fabric
200	) {
201	    CUmemGenericAllocationHandle handle;
202	    if (use_fabric) {
203	        CUmemFabricHandle fabric = {};
204	        std::memcpy(fabric.data,
205	                    handles.const_data_ptr<uint8_t>() + index * kFabricHandleBytes,
206	                    sizeof(fabric.data));
207	        CUCHECK(cuMemImportFromShareableHandle(
208	            &handle, &fabric, CU_MEM_HANDLE_TYPE_FABRIC));
209	    } else {
210	        int64_t fd = handles.const_data_ptr<int64_t>()[index];
211	        TORCH_CHECK(fd >= 0, "invalid fd ", fd, " at index ", index);
212	        CUCHECK(cuMemImportFromShareableHandle(
213	            &handle, reinterpret_cast<void *>(static_cast<intptr_t>(fd)),
214	            CU_MEM_HANDLE_TYPE_POSIX_FILE_DESCRIPTOR));
215	    }
216	    return handle;
217	}
