219	// Returns (keepalive VA tensor, shareable handle, owned mem handle as int64).
220	// The owned mem handle is not released here (kept for multicast cuMulticastBindMem);
221	// the caller must call nvl_release_mem_handle when done (buffers that do not need
222	// multicast release it immediately, matching the old behavior; buffers that need
223	// multicast release it after bind).
224	// The shareable handle is what peers import: an int64 scalar tensor holding an
225	// fd the caller must close once all peers have imported it, or a uint8[64]
226	// fabric handle that needs no cleanup.
227	inline std::tuple<at::Tensor, at::Tensor, int64_t> nvl_dist_alloc(
228	    const std::vector<int64_t> &chunk_shape,
229	    at::ScalarType dtype,
230	    bool use_fabric
231	) {
232	    auto [nbytes, allocated_size, device_id] =
233	        nvl_prepare(chunk_shape, dtype, use_fabric);
234	
235	    CUmemAllocationProp prop = {};
236	    prop.type = CU_MEM_ALLOCATION_TYPE_PINNED;
237	    prop.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
238	    prop.location.id = device_id;
239	    prop.requestedHandleTypes = nvl_handle_type(use_fabric);
240	
241	    CUmemGenericAllocationHandle mem_handle;
242	    CUCHECK(cuMemCreate(&mem_handle, allocated_size, &prop, 0));
243	
244	    CUdeviceptr dptr;
245	    CUCHECK(cuMemAddressReserve(&dptr, allocated_size, 0, 0, 0));
246	    CUCHECK(cuMemMap(dptr, allocated_size, 0, mem_handle, 0));
247	
248	    CUmemAccessDesc access_desc = {};
249	    access_desc.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
250	    access_desc.location.id = device_id;
251	    access_desc.flags = CU_MEM_ACCESS_FLAGS_PROT_READWRITE;
252	    CUCHECK(cuMemSetAccess(dptr, allocated_size, &access_desc, 1));
253	
254	    // Export for other processes to import. Do not release mem_handle: keep the
255	    // owned generic handle for multicast BindMem. The caller is responsible for
256	    // nvl_release_mem_handle. The physical memory is referenced by the unicast
257	    // map (keepalive) and (optionally) multicast; it is only truly freed after
258	    // all unmaps once the handle is released.
259	    auto shareable = nvl_export_shareable(mem_handle, use_fabric);
260	
261	    auto keepalive = make_vmm_tensor(
262	        reinterpret_cast<void *>(dptr), nbytes, allocated_size,
263	        device_id, chunk_shape, dtype);
264	
265	    return {std::move(keepalive), std::move(shareable),
266	            static_cast<int64_t>(mem_handle)};
267	}
