269	// Release the owned mem handle returned by nvl_dist_alloc (the physical memory
270	// stays alive via the existing maps).
271	static inline void nvl_release_mem_handle(int64_t mem_handle_u64) {
272	    CUCHECK(cuMemRelease(static_cast<CUmemGenericAllocationHandle>(mem_handle_u64)));
273	}
