275	/**
276	 * Map all chunk handles into a contiguous VA region.
277	 * Key difference from reference: ALL chunks get RW access (not just local_rank),
278	 * because dispatch needs to write to remote ranks' regions.
279	 *
280	 * `shareables` are the handles exported by each rank via nvl_dist_alloc and
281	 * routed to this process by the caller: POSIX fds (already valid here, the
282	 * caller may close them once imported) or 64-byte fabric blobs.
283	 */
284	inline at::Tensor nvl_dist_map(
285	    const std::vector<int64_t> &chunk_shape,
286	    at::ScalarType dtype,
287	    const at::Tensor &shareables,
288	    int64_t local_rank,
289	    int64_t world_size,
290	    bool use_fabric
291	) {
292	    nvl_check_handles(shareables, world_size, use_fabric);
293	
294	    auto [chunk_nbytes, chunk_allocated_size, device_id] =
295	        nvl_prepare(chunk_shape, dtype, use_fabric);
296	
297	    TORCH_CHECK(chunk_allocated_size == chunk_nbytes,
298	        "Chunk byte size (", chunk_nbytes, ") must be aligned to VMM granularity (",
299	        chunk_allocated_size, "). Adjust chunk dimensions so that the total bytes "
300	        "are a multiple of the allocation granularity.");
301	
302	    size_t total_allocated_size = chunk_allocated_size * world_size;
303	    size_t total_nbytes = chunk_nbytes * world_size;
304	
305	    CUdeviceptr dptr;
306	    CUCHECK(cuMemAddressReserve(&dptr, total_allocated_size, 0, 0, 0));
307	
308	    for (int64_t i = 0; i < world_size; i++) {
309	        CUmemGenericAllocationHandle mem_handle =
310	            nvl_import_shareable(shareables, i, use_fabric);
311	
312	        CUdeviceptr chunk_va = dptr + i * chunk_allocated_size;
313	        CUCHECK(cuMemMap(chunk_va, chunk_allocated_size, 0, mem_handle, 0));
314	
315	        // All chunks get RW access for dispatch writes
316	        CUmemAccessDesc access = {};
317	        access.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
318	        access.location.id = device_id;
319	        access.flags = CU_MEM_ACCESS_FLAGS_PROT_READWRITE;
320	        CUCHECK(cuMemSetAccess(chunk_va, chunk_allocated_size, &access, 1));
321	
322	        CUCHECK(cuMemRelease(mem_handle));
323	    }
324	
325	    std::vector<int64_t> full_shape = chunk_shape;
326	    full_shape[0] *= world_size;
327	
328	    int ws = world_size;
329	    size_t cas = chunk_allocated_size;
330	    size_t tas = total_allocated_size;
331	    auto deleter = [device_id, dptr, cas, ws, tas](void *p) {
332	        if (!p) return;
333	        c10::cuda::CUDAGuard guard(device_id);
334	        cudaStreamSynchronize(c10::cuda::getCurrentCUDAStream().stream());
335	        for (int i = 0; i < ws; i++) {
336	            cuMemUnmap(dptr + i * cas, cas);
337	        }
338	        cuMemAddressFree(dptr, tas);
339	    };
340	
341	    auto storage = c10::Storage(
342	        c10::Storage::use_byte_size_t(),
343	        static_cast<int64_t>(total_nbytes),
344	        at::InefficientStdFunctionContext::makeDataPtr(
345	            reinterpret_cast<void *>(dptr), std::move(deleter),
346	            c10::Device(c10::kCUDA, device_id)),
347	        /*allocator=*/nullptr,
348	        /*resizable=*/false);
349	
350	    auto impl = c10::make_intrusive<at::TensorImpl>(
351	        std::move(storage),
352	        c10::DispatchKeySet(c10::DispatchKey::CUDA),
353	        c10::scalarTypeToTypeMeta(dtype));
354	    impl->set_sizes_contiguous(full_shape);
355	    return at::Tensor(std::move(impl));
356	}
