358	// ============================================================
359	// Multicast (NVSwitch SHARP) — register once, hold persistently
360	// ============================================================
361	//
362	// Adds a multicast mapping on top of an already-allocated NVLink chunk (each
363	// rank's own cuMemCreate physical memory): bind every rank's chunk physical
364	// memory to the same multicast object, then map a multicast VA. A single
365	// multimem.st write to the multicast VA is fanned out by NVSwitch hardware to
366	// the corresponding offset of every rank's local physical memory.
367	//
368	// Uses no extra device memory — it only adds one more VA mapping over the
369	// existing chunk physical memory. Lifetime: the caller (MoonEP Buffer) holds
370	// the returned mc VA tensor, same lifetime as meta_buf; the mc VA tensor's
371	// deleter releases the multicast handle after unmap/free of the VA.
372	//
373	// Registration must follow the Python-side coordination order (separated by
374	// dist.barrier, otherwise bind fails with CUDA_ERROR_ILLEGAL_STATE or hangs):
375	//   root: nvl_multicast_create -> send the exported POSIX fd to other ranks
376	//   non-root: nvl_multicast_import
377	//   all ranks: nvl_multicast_add_device
378	//   --- dist.barrier ---
379	//   all ranks: nvl_multicast_bind_map
380	//   --- dist.barrier ---
381	
382	// Whether the device supports multicast.
383	static inline bool nvl_multicast_supported() {
384	    int device_id;
385	    CUDACHECK(cudaGetDevice(&device_id));
386	    CUdevice cu_device;
387	    CUCHECK(cuDeviceGet(&cu_device, device_id));
388	    int supported = 0;
389	    CUCHECK(cuDeviceGetAttribute(&supported,
390	        CU_DEVICE_ATTRIBUTE_MULTICAST_SUPPORTED, cu_device));
391	    return supported != 0;
392	}
393	
394	static inline size_t nvl_multicast_granularity_for(
395	    int num_devices, CUmemAllocationHandleType ht
396	) {
397	    CUmulticastObjectProp prop = {};
398	    prop.numDevices = static_cast<unsigned int>(num_devices);
399	    prop.size = 0;
400	    prop.handleTypes = ht;
401	    prop.flags = 0;
402	    size_t gran = 0;
403	    CUCHECK(cuMulticastGetGranularity(
404	        &gran, &prop, CU_MULTICAST_GRANULARITY_RECOMMENDED));
405	    return gran;
406	}
407	
408	// Recommended multicast alignment granularity (bytes). Both the addr and size
409	// of a bind must be aligned to it. Like nvl_granularity_max, this is the max
410	// over every handle type that may be used, so a buffer padded to it stays
411	// valid whichever type the process group picks.
412	static inline size_t nvl_multicast_granularity(int num_devices) {
413	    size_t gran = nvl_multicast_granularity_for(
414	        num_devices, CU_MEM_HANDLE_TYPE_POSIX_FILE_DESCRIPTOR);
415	    if (nvl_fabric_supported()) {
416	        gran = std::max(gran, nvl_multicast_granularity_for(
417	            num_devices, CU_MEM_HANDLE_TYPE_FABRIC));
418	    }
419	    return gran;
420	}
421	
422	static inline int64_t get_multicast_granularity(int64_t num_devices) {
423	    return static_cast<int64_t>(
424	        nvl_multicast_granularity(static_cast<int>(num_devices)));
425	}
426	
427	// root only: create the multicast object and export it for the other ranks.
428	// Returns (mc_handle as uint64, shareable handle).
429	// mc_handle is a handle value valid within this process; Python holds it and
430	// passes it back unchanged to bind_map. The caller passes the shareable handle
431	// to the other ranks (closing the fd, if it is one, after all have imported).
432	inline std::tuple<int64_t, at::Tensor> nvl_multicast_create(
433	    int64_t size_bytes, int64_t num_devices, bool use_fabric
434	) {
435	    TORCH_CHECK(nvl_multicast_supported(),
436	        "Multicast not supported on this device");
437	    const size_t gran = nvl_multicast_granularity(static_cast<int>(num_devices));
438	    const size_t aligned =
439	        (static_cast<size_t>(size_bytes) + gran - 1) / gran * gran;
440	
441	    CUmulticastObjectProp prop = {};
442	    prop.numDevices = static_cast<unsigned int>(num_devices);
443	    prop.size = aligned;
444	    prop.handleTypes = nvl_handle_type(use_fabric);
445	    prop.flags = 0;
446	
447	    CUmemGenericAllocationHandle mc_handle;
448	    CUCHECK(cuMulticastCreate(&mc_handle, &prop));
449	
450	    auto shareable = nvl_export_shareable(mc_handle, use_fabric);
451	    return {static_cast<int64_t>(mc_handle), std::move(shareable)};
452	}
453	
454	// non-root: import the multicast object from the handle sent by root. If it is
455	// an fd, the caller may close it once imported.
456	inline int64_t nvl_multicast_import(
457	    const at::Tensor &shareable, bool use_fabric
458	) {
459	    auto one = use_fabric ? shareable.view({1, kFabricHandleBytes})
460	                          : shareable.view({1});
461	    nvl_check_handles(one, 1, use_fabric);
462	    return static_cast<int64_t>(nvl_import_shareable(one, 0, use_fabric));
463	}
