465	// all ranks: add this rank's device to the multicast group. Must happen before
466	// bind, and bind may only happen after all ranks have added (dist.barrier).
467	inline void nvl_multicast_add_device(int64_t mc_handle_u64) {
468	    int device_id;
469	    CUDACHECK(cudaGetDevice(&device_id));
470	    CUdevice cu_device;
471	    CUCHECK(cuDeviceGet(&cu_device, device_id));
472	    CUCHECK(cuMulticastAddDevice(
473	        static_cast<CUmemGenericAllocationHandle>(mc_handle_u64), cu_device));
474	}
475	
476	// all ranks: bind this rank's local chunk owned physical memory (the mem
477	// handle kept by nvl_dist_alloc) to the multicast object, then reserve a VA
478	// for the multicast handle + map + setAccess. Returns an int32 keepalive
479	// tensor holding the multicast VA (.data_ptr() is the multimem address). Uses
480	// BindMem (owned handle) instead of BindAddr: BindAddr returns invalid
481	// argument for IPC-imported VAs on this platform.
482	inline at::Tensor nvl_multicast_bind_map(
483	    int64_t mc_handle_u64, int64_t owned_mem_handle_u64,
484	    int64_t size_bytes, int64_t num_devices
485	) {
486	    int device_id;
487	    CUDACHECK(cudaGetDevice(&device_id));
488	    CUmemGenericAllocationHandle mc_handle =
489	        static_cast<CUmemGenericAllocationHandle>(mc_handle_u64);
490	    CUmemGenericAllocationHandle mem_handle =
491	        static_cast<CUmemGenericAllocationHandle>(owned_mem_handle_u64);
492	
493	    const size_t gran = nvl_multicast_granularity(static_cast<int>(num_devices));
494	    TORCH_CHECK(static_cast<size_t>(size_bytes) % gran == 0,
495	        "multicast bind size (", size_bytes, ") must be a multiple of multicast "
496	        "granularity (", gran, "); pad meta_buf chunk accordingly");
497	    const size_t size = static_cast<size_t>(size_bytes);
498	
499	    // Bind this rank's owned physical allocation to offset 0 of the multicast object.
500	    CUCHECK(cuMulticastBindMem(
501	        mc_handle, /*mcOffset=*/0, mem_handle, /*memOffset=*/0, size, 0));
502	
503	    // Reserve a separate VA for the multicast handle and map it. Pass 0 for
504	    // alignment (the driver aligns to granularity by default, same as
505	    // nvl_dist_alloc/nvl_dist_map; a non-zero alignment is rejected by
506	    // cuMemAddressReserve as invalid argument).
507	    CUdeviceptr mc_va;
508	    CUCHECK(cuMemAddressReserve(&mc_va, size, 0, 0, 0));
509	    CUCHECK(cuMemMap(mc_va, size, 0, mc_handle, 0));
510	
511	    CUmemAccessDesc access = {};
512	    access.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
513	    access.location.id = device_id;
514	    access.flags = CU_MEM_ACCESS_FLAGS_PROT_READWRITE;
515	    CUCHECK(cuMemSetAccess(mc_va, size, &access, 1));
516	
517	    // keepalive: the deleter unmaps + frees the VA, then releases mc_handle.
